//! The one SQLite database file Crumble keeps, its migrations and the schema they produce.
//! Domain crates such as `crumble-store` and `crumble-notes` each open their own connection
//! through [`open_file`] and own their queries.

/// The tables, as `diesel print-schema` writes them; regenerated, never edited by hand.
#[allow(missing_docs, reason = "generated by Diesel, which writes no docs")]
pub mod schema;

use std::path::PathBuf;

use anyhow::anyhow;
use diesel::connection::SimpleConnection;
use diesel::prelude::*;
use diesel_migrations::{EmbeddedMigrations, MigrationHarness, embed_migrations};

/// Every migration in `migrations/`. Diesel records each by the date its folder name starts with,
/// so a folder keeps its name for good.
const MIGRATIONS: EmbeddedMigrations = embed_migrations!();

/// `~/Library/Application Support/Crumble/crumble.sqlite3`, its folder created when missing.
fn path() -> anyhow::Result<PathBuf> {
    let dir = dirs::data_dir()
        .ok_or_else(|| anyhow!("no data directory"))?
        .join("Crumble");
    std::fs::create_dir_all(&dir)?;
    Ok(dir.join("crumble.sqlite3"))
}

/// Opens the app's database file and runs pending migrations.
pub fn open_file() -> anyhow::Result<SqliteConnection> {
    let path = path()?;
    let url = path
        .to_str()
        .ok_or_else(|| anyhow!("{} is not UTF-8", path.display()))?;
    open(url)
}

/// Opens the database at `url`, `:memory:` included, and runs pending migrations. Every
/// connection enforces foreign keys and waits up to 5 s for a lock; a file also switches to WAL,
/// so the connections the domain crates keep read while another one writes.
pub fn open(url: &str) -> anyhow::Result<SqliteConnection> {
    let mut connection = SqliteConnection::establish(url)?;
    // One PRAGMA per statement, the timeout first, as Diesel's `SqliteConnection` docs advise.
    connection.batch_execute("PRAGMA busy_timeout = 5000;")?;
    connection.batch_execute("PRAGMA foreign_keys = ON;")?;
    if url != ":memory:" {
        connection.batch_execute("PRAGMA journal_mode = WAL;")?;
    }
    connection
        .run_pending_migrations(MIGRATIONS)
        .map_err(|error| anyhow!(error))?;
    Ok(connection)
}

#[cfg(test)]
mod tests {
    use diesel::dsl::sql;
    use diesel::prelude::*;
    use diesel::sql_types::{Integer, Text};
    use diesel_migrations::MigrationHarness;

    use super::open;

    fn journal_mode(connection: &mut SqliteConnection) -> QueryResult<String> {
        diesel::select(sql::<Text>(
            "(SELECT journal_mode FROM pragma_journal_mode())",
        ))
        .get_result(connection)
    }

    #[test]
    fn a_file_uses_wal_and_keeps_the_moved_migration_version() {
        let path = std::env::temp_dir().join(format!(
            "crumble-db-test-{}-{:?}.sqlite3",
            std::process::id(),
            std::time::SystemTime::now()
        ));
        let url = path.to_string_lossy().into_owned();
        let open = || open(&url).unwrap_or_else(|error| panic!("{error}"));
        let mut connection = open();
        assert_eq!(journal_mode(&mut connection).as_deref(), Ok("wal"));
        let foreign_keys = diesel::select(sql::<Integer>(
            "(SELECT foreign_keys FROM pragma_foreign_keys())",
        ))
        .get_result::<i32>(&mut connection);
        assert_eq!(foreign_keys, Ok(1));
        // The version `crumble-store` recorded before the migration moved here, so a database
        // migrated then does not run it again.
        let applied = connection
            .applied_migrations()
            .unwrap_or_else(|error| panic!("{error}"));
        assert!(
            applied
                .iter()
                .any(|version| version.to_string() == "20261016000000")
        );
        let updated = diesel::sql_query("UPDATE app_state SET first_day_of_week = 6")
            .execute(&mut connection);
        assert_eq!(updated, Ok(1));
        drop(connection);
        let day = diesel::select(sql::<Integer>("(SELECT first_day_of_week FROM app_state)"))
            .get_result::<i32>(&mut open());
        for suffix in ["", "-wal", "-shm"] {
            let _ = std::fs::remove_file(format!("{url}{suffix}"));
        }
        assert_eq!(day, Ok(6));
    }

    #[test]
    fn memory_skips_wal() {
        let mut connection = open(":memory:").unwrap_or_else(|error| panic!("{error}"));
        assert_eq!(journal_mode(&mut connection).as_deref(), Ok("memory"));
    }
}
